from src.processor import process_items, format_result


def test_process_items_filters_empty():
    assert process_items(['a', '', 'b']) == ['a', 'b']


def test_process_items_respects_limit():
    items = [str(i) for i in range(200)]
    assert len(process_items(items, limit=5)) == 5


def test_format_result_comma_separated():
    assert format_result(['x', 'y', 'z']) == 'x, y, z'
